From 868c4255d13e4edec35b76ae98d271f65adafc1d Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 15:35:43 +0100
Subject: [PATCH] libnotificationmanager: Show desktop:/ URLs as a pretty local
 path

Deleting a file on the desktop showed the raw "desktop:/" URL in the
notification, with "[" shown as "%5B", since only places and local files
were prettified. Map desktop:/ to the Desktop folder before the lookup.

BUG: 526047
---
 libnotificationmanager/job_p.cpp | 11 +++++++++++
 1 file changed, 11 insertions(+)

diff --git a/libnotificationmanager/job_p.cpp b/libnotificationmanager/job_p.cpp
index 87c685401a..6a6a3113ae 100644
--- a/libnotificationmanager/job_p.cpp
+++ b/libnotificationmanager/job_p.cpp
@@ -10,6 +10,7 @@

 #include <QDBusConnection>
 #include <QDebug>
+#include <QStandardPaths>

 #include <KFilePlacesModel>
 #include <KIO/StatJob>
@@ -148,6 +149,16 @@ QString JobPrivate::prettyUrl(const QUrl &_url) const
         url.setPath(url.path().chopped(2));
     }

+    // desktop:/ merely forwards to the Desktop folder, which may no longer contain the file
+    // (e.g. after deleting it), so map it here rather than asking KIO for the most local URL.
+    if (url.scheme() == QLatin1String("desktop")) {
+        QString path = url.path(QUrl::FullyDecoded);
+        if (!path.startsWith(QLatin1Char('/'))) {
+            path.prepend(QLatin1Char('/'));
+        }
+        url = QUrl::fromLocalFile(QStandardPaths::writableLocation(QStandardPaths::DesktopLocation) + path).adjusted(QUrl::StripTrailingSlash);
+    }
+
     if (!m_placesModel) {
         m_placesModel = createPlacesModel();
     }
